insert into questions (id, type, data, status) values ('q_sba_epidural_space_layers_001', 'SBA', '{"dateAdded":"2026-10-07","rotationIndex":137,"question":"During a midline lumbar epidural, which structure is crossed immediately before the needle tip enters the epidural space?","choices":["Supraspinous ligament","Interspinous ligament","Ligamentum flavum","Posterior longitudinal ligament","Dura mater"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">On a midline approach the needle crosses skin, subcutaneous tissue, supraspinous ligament, interspinous ligament and then ligamentum flavum, after which a loss of resistance signals entry to the epidural space (see the knowledge box below).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> The supraspinous ligament is the first firm structure encountered, but it lies superficial to the interspinous ligament and ligamentum flavum.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> The interspinous ligament lies between the supraspinous ligament and the ligamentum flavum, so it is not the last structure before the epidural space.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> The ligamentum flavum is the deepest structure traversed before the epidural space, and the loss of resistance used to identify the space occurs as the needle passes through it.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> The posterior longitudinal ligament forms the anterior boundary of the epidural space and is never crossed during a posterior approach.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> The dura mater lies on the far side of the epidural space; crossing it means a dural puncture and entry to the subarachnoid space.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Epidural Space Anatomy</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The epidural (extradural) space is the fat-filled potential space between the dura mater and the vertebral canal wall. Knowing the layers crossed on a midline approach &mdash; and the feel of each &mdash; underpins both epidural and caudal techniques.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Layers Crossed (Midline Lumbar Approach)</div><table style=\"margin:0\"><tr><th>Order</th><th>Structure</th><th>Note</th></tr><tr><td>1</td><td>Skin</td><td>Skin-to-epidural-space distance is typically about 4&ndash;6 cm in adults but varies widely with body habitus</td></tr><tr><td>2</td><td>Subcutaneous tissue</td><td>Fat; loose resistance</td></tr><tr><td>3</td><td>Supraspinous ligament</td><td>Runs over the tips of the spinous processes; the first firm resistance</td></tr><tr><td>4</td><td>Interspinous ligament</td><td>Joins adjacent spinous processes; continues deeply into the ligamentum flavum</td></tr><tr><td>5</td><td>Ligamentum flavum</td><td>Elastic, paired ligament joining adjacent laminae; thickest in the lumbar region and gives a distinct gritty, leathery resistance</td></tr><tr><td>6</td><td>Epidural space</td><td>Loss of resistance as the needle passes through the ligamentum flavum</td></tr><tr><td>7</td><td>Dura mater</td><td>Deliberate or accidental puncture leads to the subarachnoid space (dural puncture)</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">A paramedian approach avoids the supraspinous and interspinous ligaments and meets the ligamentum flavum directly.</p><div style=\"text-align:center\"><img src=\"images/epidural-layers.svg\" alt=\"Diagram of the structures crossed by a needle on a midline lumbar approach to the epidural space: skin, subcutaneous fat, supraspinous ligament, interspinous ligament, ligamentum flavum, epidural space and dura\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Boundaries</div><table style=\"margin:0\"><tr><th>Boundary</th><th>Structure</th></tr><tr><td>Superior</td><td>Foramen magnum, where the dura fuses with the periosteum</td></tr><tr><td>Inferior</td><td>Sacrococcygeal membrane at the sacral hiatus</td></tr><tr><td>Anterior</td><td>Posterior longitudinal ligament covering the vertebral bodies and discs</td></tr><tr><td>Posterior</td><td>Ligamentum flavum and the laminae</td></tr><tr><td>Lateral</td><td>Pedicles and the intervertebral foramina, through which the space communicates with the paravertebral space</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Contents</div><table style=\"margin:0\"><tr><th>Contents of the epidural space</th></tr><tr><td>Epidural fat (a depot for lipid-soluble drugs such as fentanyl)</td></tr><tr><td>Internal vertebral venous plexus (Batson&rsquo;s plexus), which is valveless &mdash; the reason for intravascular injection and epidural haematoma risk</td></tr><tr><td>Spinal nerve roots (dura-sheathed) as they pass towards the intervertebral foramina</td></tr><tr><td>Lymphatics and loose areolar connective tissue</td></tr><tr><td>Small arterial branches from the segmental spinal arteries</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Depth of the Space</div><table style=\"margin:0\"><tr><th>Region</th><th>Approximate posterior depth</th></tr><tr><td>Cervical</td><td>1&ndash;2 mm (narrowest)</td></tr><tr><td>Thoracic</td><td>2.5&ndash;4 mm</td></tr><tr><td>Lumbar</td><td>5&ndash;6 mm (widest, at about L2)</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">The adult spinal cord ends at about L1&ndash;L2 and the dural sac at about S2, which is why lumbar epidural placement below L2 is safest.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_lumbar_plexus_001', 'MTF', '{"dateAdded":"2026-10-07","rotationIndex":138,"stem":"Regarding the lumbar plexus:","choices":["It is formed from the anterior rami of L1 to L4","It lies within the substance of psoas major","The femoral nerve arises from the L1 to L3 roots","The obturator nerve emerges from the medial border of psoas major","The genitofemoral nerve arises from the L3 and L4 roots"],"correct":[true,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lumbar plexus is formed within psoas major from the anterior rami of L1&ndash;L4 (with a contribution from T12) and gives rise to the iliohypogastric, ilioinguinal, genitofemoral, lateral femoral cutaneous, femoral and obturator nerves.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; The plexus is formed from the anterior (ventral) rami of L1&ndash;L4, with a variable contribution from T12.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; The plexus lies within the substance of psoas major, in its posterior part and anterior to the lumbar transverse processes. This is the basis of the psoas compartment block.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; The femoral nerve arises from the <strong>L2&ndash;L4</strong> roots, not L1&ndash;L3.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; The obturator nerve (L2&ndash;L4) emerges from the medial border of psoas major and passes through the obturator canal. The femoral nerve emerges from the lateral border.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; The genitofemoral nerve arises from <strong>L1&ndash;L2</strong>, not L3&ndash;L4. It emerges on the anterior surface of psoas major.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Lumbar Plexus</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lumbar plexus forms within the substance of psoas major from the anterior (ventral) rami of L1&ndash;L4, with a variable contribution from T12. It supplies the lower abdominal wall, anterior and medial thigh and the genital region.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Branches</div><table style=\"margin:0\"><tr><th>Nerve</th><th>Roots</th><th>Course and function</th></tr><tr><td>Iliohypogastric</td><td>L1 (T12)</td><td>Emerges from the lateral border of psoas; sensory to the suprapubic and lateral gluteal skin and motor to the lower abdominal wall muscles</td></tr><tr><td>Ilioinguinal</td><td>L1</td><td>Lateral border of psoas; travels through the inguinal canal; sensory to the groin, upper medial thigh and anterior scrotum or labia</td></tr><tr><td>Genitofemoral</td><td>L1&ndash;L2</td><td>Pierces and emerges on the anterior surface of psoas; genital branch (cremaster) and femoral branch (skin below the inguinal ligament)</td></tr><tr><td>Lateral femoral cutaneous</td><td>L2&ndash;L3</td><td>Lateral border of psoas; purely sensory to the anterolateral thigh</td></tr><tr><td>Femoral</td><td>L2&ndash;L4</td><td>Lateral border of psoas, in the groove between psoas and iliacus; quadriceps, sartorius and anterior thigh skin; saphenous nerve to the medial leg</td></tr><tr><td>Obturator</td><td>L2&ndash;L4</td><td>Medial border of psoas; adductor compartment of the thigh and a variable patch of medial thigh skin</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Exits from psoas: the genitofemoral emerges anteriorly, the obturator medially, and the femoral, lateral femoral cutaneous, ilioinguinal and iliohypogastric laterally.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Relevance to Pain Medicine</div><table style=\"margin:0\"><tr><th>Key points</th></tr><tr><td>The plexus lies in the posterior part of psoas major, anterior to the lumbar transverse processes, which is the target of the psoas compartment (lumbar plexus) block</td></tr><tr><td>Genitofemoral neuralgia is a recognised complication of lumbar sympathetic neurolysis, because the nerve runs on the anterior surface of psoas close to the sympathetic chain</td></tr><tr><td>Ilioinguinal and iliohypogastric injury after lower abdominal surgery causes groin pain and sensory loss</td></tr><tr><td>The obturator nerve can be blocked for hip joint pain and adductor spasm</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_lumbar_facet_joint_innervation_001', 'MTF', '{"dateAdded":"2026-10-07","rotationIndex":139,"stem":"Regarding the innervation of the lumbar facet (zygapophyseal) joints:","choices":["Each joint is supplied by medial branches from two adjacent spinal levels","The medial branch passes anterior to the transverse process, close to the intervertebral foramen","The L5 dorsal ramus is the target for blocking the nerve supply to the L5/S1 joint, together with the L4 medial branch","The medial branches also supply multifidus","The joints are supplied by the anterior (ventral) primary rami"],"correct":[true,false,true,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lumbar facet joints are supplied by the medial branches of the dorsal (posterior) primary rami, each joint receiving dual supply from adjacent levels (see the knowledge box below).</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Each joint receives medial branches from the level above and the level below it, for example the L4/5 joint from the L3 and L4 medial branches. Two nerves must therefore be blocked or denervated per joint.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; The medial branch runs <strong>posteriorly</strong>: it crosses the junction of the superior articular process and the transverse process, away from the foramen, which is why it can be targeted fluoroscopically without entering the foramen.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; At L5 the dorsal ramus itself (rather than a medial branch) runs in the groove between the sacral ala and the S1 superior articular process. With the L4 medial branch it supplies the L5/S1 joint.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Medial branches give segmental motor supply to multifidus and the interspinous muscles, so radiofrequency denervation can cause multifidus atrophy.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; The facet joints are supplied by the <strong>dorsal</strong> primary rami. Ventral rami form the plexuses and supply the anterior structures.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Lumbar Facet Joint Innervation</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Each lumbar zygapophyseal (facet) joint is supplied by the medial branches of the dorsal rami of two adjacent spinal levels. This dual supply is why diagnostic medial branch blocks and radiofrequency denervation must target two nerves for every painful joint.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Dorsal ramus</td><td>Arises from the spinal nerve just outside the intervertebral foramen and divides into medial, intermediate and lateral branches</td></tr><tr><td>Medial branch (L1&ndash;L4)</td><td>Runs across the junction of the superior articular process and the transverse process, then under the mamillo-accessory ligament, and supplies the joint above and the joint below</td></tr><tr><td>Joint supply</td><td>The L4/5 joint is supplied by the L3 and L4 medial branches; the L3/4 joint by the L2 and L3 medial branches</td></tr><tr><td>L5 level</td><td>The L5 dorsal ramus (not a medial branch) crosses the groove between the sacral ala and the S1 superior articular process; with the L4 medial branch it supplies the L5/S1 joint</td></tr><tr><td>Other supply</td><td>The medial branch also supplies multifidus, interspinous muscles and ligaments, and periosteum at the same segment</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">The facet joints are innervated by the posterior (dorsal) primary rami, not the anterior (ventral) rami.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Procedural Targets</div><table style=\"margin:0\"><tr><th>Level</th><th>Target for medial branch block or radiofrequency</th></tr><tr><td>L1&ndash;L4 medial branches</td><td>The junction of the superior articular process and the transverse process (the &ldquo;eye of the Scotty dog&rdquo; on oblique views)</td></tr><tr><td>L5 dorsal ramus</td><td>The groove between the S1 superior articular process and the sacral ala</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Facet joint pain is diagnosed by dual diagnostic medial branch blocks; radiofrequency denervation follows only after a positive block response.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_third_occipital_nerve_c2_3_joint_001', 'SBA', '{"dateAdded":"2026-10-07","rotationIndex":140,"question":"A 38-year-old woman has persistent unilateral occipital headache following a whiplash injury, and a diagnostic block is planned for the C2/3 zygapophyseal joint. Which nerve provides the main sensory supply to this joint?","choices":["Greater occipital nerve","Lesser occipital nerve","Third occipital nerve","Ventral ramus of C2","Great auricular nerve"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The C2/3 zygapophyseal joint is supplied by the third occipital nerve, the superficial medial branch of the dorsal ramus of C3. It is the target for diagnostic blocks and radiofrequency denervation in cervicogenic headache.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> The greater occipital nerve is the medial branch of the C2 dorsal ramus and supplies the posterior scalp. It is a target for occipital nerve blocks, but it is not the main supply of the C2/3 joint.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> The lesser occipital nerve is a branch of the cervical plexus (ventral rami C2&ndash;C3) and supplies the scalp behind the ear.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> The third occipital nerve crosses the dorsolateral aspect of the C2/3 joint and supplies it. It also supplies a small patch of suboccipital skin.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> The ventral ramus of C2 supplies the lateral atlantoaxial (C1/2) joint rather than the C2/3 joint.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> The great auricular nerve is a cervical plexus branch supplying skin over the parotid and ear; it does not innervate cervical joints.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Cervical Facet Joints and Occipital Nerves</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The cervical zygapophyseal joints are a recognised source of neck pain and cervicogenic headache, with referred pain patterns that map to the level involved. The C2/3 joint is clinically important because its nerve, the third occipital nerve, is a target in cervicogenic headache.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Occipital Nerves</div><table style=\"margin:0\"><tr><th>Nerve</th><th>Origin</th><th>Territory</th></tr><tr><td>Greater occipital</td><td>Medial branch of the C2 dorsal ramus</td><td>Posterior scalp to the vertex</td></tr><tr><td>Third occipital</td><td>Superficial medial branch of the C3 dorsal ramus</td><td>C2/3 zygapophyseal joint and a small area of suboccipital skin</td></tr><tr><td>Lesser occipital</td><td>Ventral rami of C2&ndash;C3 (cervical plexus)</td><td>Scalp behind the ear</td></tr><tr><td>Great auricular</td><td>Ventral rami of C2&ndash;C3 (cervical plexus)</td><td>Skin over the parotid and the ear</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Points</div><table style=\"margin:0\"><tr><th>Key points</th></tr><tr><td>The C2/3 joint is a common source of cervicogenic headache, including after whiplash injury</td></tr><tr><td>Diagnosis is by controlled (dual) anaesthetic blocks of the third occipital nerve, which is blocked at three levels above, at and below the joint because it crosses the joint obliquely</td></tr><tr><td>The C3 to C7 joints are supplied by medial branches of the dorsal rami above and below the joint, in the same way as the lumbar joints</td></tr><tr><td>The C1/2 (lateral atlantoaxial) joint is supplied by the ventral ramus of C2, so it cannot be treated with a medial branch technique</td></tr><tr><td>Radiofrequency denervation of the third occipital nerve can leave numbness of the suboccipital skin</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_lumbar_sympathetic_chain_relations_001', 'SBA', '{"dateAdded":"2026-10-07","rotationIndex":141,"question":"During a right-sided lumbar sympathetic block at L3, which structure lies directly anterior to the right sympathetic chain and is at risk of intravascular injection?","choices":["Abdominal aorta","Inferior vena cava","Right ureter","Psoas major","Right kidney"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The right lumbar sympathetic chain lies on the anterolateral surface of the vertebral bodies and is partly covered by the inferior vena cava, while the left chain lies lateral to the aorta. This is why a needle that is placed too far anteriorly on the right risks puncturing the cava.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> The abdominal aorta lies left of midline and is related to the left chain (which lies lateral to it). On the right, the IVC lies between the aorta and the chain.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> The inferior vena cava lies directly anterior to, and partly overlaps, the right lumbar sympathetic chain. Intravascular injection and venous bleeding are recognised hazards.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> The ureter descends on the anterior surface of psoas major, lateral to the chain, and is at risk if the needle is too lateral rather than anterior.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Psoas major lies posterolateral to the chain; the chain runs along its medial border.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> The kidney lies lateral and posterior in the retroperitoneum at this level, away from the sympathetic chain.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Lumbar Sympathetic Chain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The lumbar sympathetic chain lies on the anterolateral surface of the lumbar vertebral bodies along the medial edge of psoas major, and supplies sympathetic fibres to the lower limb and pelvis. Lumbar sympathetic block is used for lower limb sympathetically maintained pain, CRPS and ischaemic pain.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy and Relations</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Position</td><td>Anterolateral to the lumbar vertebral bodies, along the medial border of psoas major, deep to the inferior vena cava (right) and lateral to the aorta (left)</td></tr><tr><td>Right chain</td><td>Lies behind the inferior vena cava, which is partly overlapping it</td></tr><tr><td>Left chain</td><td>Lies lateral to the abdominal aorta, with the lateral aortic lymph nodes anterior</td></tr><tr><td>Ganglia</td><td>Typically four to five, with variable position; the L2 and L3 ganglia are the most constant and the usual target</td></tr><tr><td>Preganglionic fibres</td><td>Arise from the lateral horn at T10&ndash;L2; the white rami communicantes exist only at T1&ndash;L2</td></tr><tr><td>Postganglionic fibres</td><td>Reach all lumbar and sacral spinal nerves by grey rami communicantes, giving sympathetic supply to the lower limb</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Block Technique and Hazards</div><table style=\"margin:0\"><tr><th>Aspect</th><th>Detail</th></tr><tr><td>Needle target</td><td>Anterolateral edge of the L2 or L3 vertebral body (fluoroscopy or CT guidance), with contrast confirming spread along the anterior psoas fascia</td></tr><tr><td>Hazards</td><td>Intravascular injection (IVC and aorta), retroperitoneal haematoma, ureteric or renal injury, epidural or subarachnoid spread, somatic nerve root block, and genitofemoral neuralgia after neurolysis</td></tr><tr><td>Evidence of success</td><td>Skin temperature rise and loss of sympathetic skin response in the limb</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;

